// Chapter 6 cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch6).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['the-day-gary-quit', ["A memory node, from the oldest backup in the vault", "Gary at the console, packing a box", "A hooded figure waits in the doorway", "why do you want to be my Champion", "I like to stand near whoever", "Gary walks out past him", "Ah ha ha."]],
    ['the-offer-on-the-jetty', ["At the end of the jetty, Freya is waiting", "All four of you, at once", "I'll bring them back. Bram, Hana, Jin, Lina", "Then she says it again, in their voices", "No. He'd hate being remembered by you", "Hana was never a recipe", "I've met Jin's Echo", "No. Lina was real", ["(Bram, in her voice", "(Hana. She even laughs", "(Up, Minnow", "(Lina's voice. The exact pitch"], ["No, love.", "No."], "Free, my loves", "someone has set up a stall"]],
    ['the-mirror', ["Where the jetty ends, the lake is brightest", "It isn't unhappy", "I finished it, love. The list", "She's right here. On the shelf", "The Cult goes down the mountain", "Sit down, Dutch. You've earned it", "Bram would have hated it", "Kai thinks of his own shelf", "You would.", "The badge on its chest is polished", "He would. I don't mind"]],
    ['the-ring-in-the-bunker', ["Seymour opens his bunker for the first time", "Kagemaru is already inside", "He lowers his hood", "Then he takes off his left glove", "They stopped praying", "Her Champion, since the day Gary said no", "I only said yes when she promised", "Desperate people", "My lady asked me to delete this", "He takes the tape: Seymour's original", "Come and see me at the top", "The copies you carry still work", "In the ledger he left on the case"]],
    ['the-clock-room-intro', ["The countdown above the key reads"]],
    ['the-clock-room', ["someone plays Cancel Deletion", "The key survives", "Saved it? Touching", "That's why you test them"]],
    ['the-confrontation', ["The Keeper's Room. On the card table", "I won't deny a thing"]],
    ['the-confrontation-shore', ["On the near shore, a stretch"]],
    ['the-confrontation-copy', ["A second copy would have halved"]],
    ['the-confrontation-bravo', ["Both shores, all at once", "Bravo! Bravo."]],
    ['no-my-lady', ["Beaten, Kagemaru sits on the floor", "Delete the tape, love. Now.", "He looks up at the ceiling for a long time", "No, my lady. I don't think I will", "The third time anyone has said no to her", "Keep winning and it stays with you", "Seymour's tape is theirs"]],
    ['switched-sides', ["I've switched sides, you know"]],
    ['kagemarus-choice', [["In the vault. With her backup", "One stall. Every sale logged", "Nothing else. Every action logged", "Come to camp. Help where you like"]]],
    ['the-backlog', ["That night Uptima searches the backlog", "There isn't one from Kagemaru"]],
    ['the-freed-floors', ["The Mirror Floors freed", "people are suddenly alone", "The relay station opens"]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
